                <h3>平均等待/诊疗时间</h3>
              </div>
            </template>
            <div ref="waitingTimeChart" class="chart-container"></div>
          </el-card>
        </el-col>
      </el-row>

      <!-- 眼科疾病分布图表 -->
      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
