              </div>
            </template>
            <div ref="diseaseDistributionChart" class="chart-container"></div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>AI诊断准确率分析</h3>
