              <div class="progress-value">20%</div>
              <div class="progress-label">病历入库量14000元</div>
            </div>
          </el-col>
          <el-col :xs="24" :sm="12" :md="6" :lg="6">
            <div class="progress-item">
              <h4>住院占比</h4>
              <div ref="inpatientProgress" class="progress-chart"></div>
              <div class="progress-value">10%</div>
              <div class="progress-label">病历入库量7000元</div>
