          <el-col :xs="24" :sm="12" :md="6" :lg="6">
            <div class="progress-item">
              <h4>抗菌药占比</h4>
              <div ref="antibioticProgress" class="progress-chart"></div>
              <div class="progress-value">6%</div>
              <div class="progress-label">病历入库量4200元</div>
            </div>
          </el-col>
          <el-col :xs="24" :sm="12" :md="6" :lg="6">
            <div class="progress-item">
              <h4>医师收入</h4>
              <div ref="hospitalRevenueProgress" class="progress-chart"></div>
              <div class="progress-value">19%</div>
              <div class="progress-label">病历入库量11900元</div>
            </div>
          </el-col>
        </el-row>
      </el-card>

      <!-- 保留原有的异常病例分析 -->
      <el-card class="anomaly-card"> // ... existing code ... </el-card>
    </div>
  </app-layout>
</template>

<script>
import AppLayout from "@/components/AppLayout.vue";
import * as echarts from "echarts";

export default {
  name: "AnalyticsView",
  components: {
    AppLayout,
  },
  data() {
    return {
      filterForm: {
        timeRange: "30days",
        department: ["outpatient"],
      },
      trendChartType: "daily",
      charts: {
        trendChart: null,
        diseaseDistributionChart: null,
        ageDistributionChart: null,
        genderDistributionChart: null,
        revenueGaugeChart: null,
        patientGaugeChart: null,
        patientFlowChart: null,
        visitTrendChart: null,
        waitingTimeChart: null,
        deptRevenueChart: null,
        deptVisitChart: null,
        outpatientProgress: null,
        inpatientProgress: null,
        antibioticProgress: null,
        hospitalRevenueProgress: null,
        accuracyChart: null,
      },
      anomalyCases: [],
    };
  },
  methods: {
    updateCharts() {
      this.updateTrendChart();
      this.updateDiseaseDistributionChart();
      this.updateAgeDistributionChart();
      this.updateGenderDistributionChart();
      this.updateAnomalyCases();

      // 新增图表的更新方法
      this.updateRevenueGaugeChart();
      this.updatePatientGaugeChart();
      this.updatePatientFlowChart();
      this.updateVisitTrendChart();
      this.updateWaitingTimeChart();
      this.updateDeptRevenueChart();
      this.updateDeptVisitChart();
      this.updateProgressCharts();
      this.updateAccuracyChart();
    },

    // ... existing methods ...

    // 新增图表初始化方法
    updateRevenueGaugeChart() {
      if (!this.charts.revenueGaugeChart) {
        this.charts.revenueGaugeChart = echarts.init(
          this.$refs.revenueGaugeChart
        );
      }

      const option = {
        series: [
          {
            type: "gauge",
            startAngle: 90,
            endAngle: -270,
            pointer: {
              show: false,
            },
            progress: {
              show: true,
              overlap: false,
              roundCap: true,
              clip: false,
              itemStyle: {
                color: "#409EFF",
              },
            },
            axisLine: {
              lineStyle: {
                width: 20,
                color: [[1, "#1E3A6E"]],
              },
            },
            splitLine: {
              show: false,
            },
            axisTick: {
              show: false,
            },
            axisLabel: {
              show: false,
            },
            data: [
              {
                value: 1100,
                name: "例",
                title: {
                  offsetCenter: ["0%", "0%"],
                },
                detail: {
                  offsetCenter: ["0%", "0%"],
                },
              },
            ],
            title: {
              fontSize: 14,
            },
            detail: {
              width: 80,
              height: 14,
              fontSize: 28,
              color: "#fff",
              backgroundColor: "auto",
              formatter: "{value}",
              borderRadius: 3,
            },
          },
        ],
      };

      this.charts.revenueGaugeChart.setOption(option);
    },

    updatePatientGaugeChart() {
      if (!this.charts.patientGaugeChart) {
        this.charts.patientGaugeChart = echarts.init(
          this.$refs.patientGaugeChart
        );
      }

      const option = {
        series: [
          {
            type: "gauge",
            startAngle: 90,
            endAngle: -270,
            pointer: {
              show: false,
            },
            progress: {
              show: true,
              overlap: false,
              roundCap: true,
              clip: false,
              itemStyle: {
                color: "#67C23A",
              },
            },
            axisLine: {
              lineStyle: {
                width: 20,
                color: [[1, "#1E3A6E"]],
              },
            },
            splitLine: {
              show: false,
            },
            axisTick: {
              show: false,
            },
            axisLabel: {
              show: false,
            },
            data: [
              {
                value: 440,
                name: "人次",
                title: {
                  offsetCenter: ["0%", "0%"],
                },
                detail: {
                  offsetCenter: ["0%", "0%"],
                },
              },
            ],
            title: {
              fontSize: 14,
            },
            detail: {
              width: 80,
              height: 14,
              fontSize: 28,
              color: "#fff",
              backgroundColor: "auto",
              formatter: "{value}",
              borderRadius: 3,
            },
          },
        ],
      };

      this.charts.patientGaugeChart.setOption(option);
    },

    updatePatientFlowChart() {
      if (!this.charts.patientFlowChart) {
        this.charts.patientFlowChart = echarts.init(
          this.$refs.patientFlowChart
        );
      }

      const option = {
        radar: {
          indicator: [
            { name: "医疗质量", max: 100 },
            { name: "诊断准确", max: 100 },
            { name: "诊断费用", max: 100 },
            { name: "患者满意", max: 100 },
            { name: "服务态度", max: 100 },
            { name: "环境舒适", max: 100 },
          ],
          shape: "polygon",
          splitNumber: 5,
          axisName: {
            color: "#428BD4",
          },
          splitLine: {
            lineStyle: {
              color: "rgba(66, 139, 212, 0.3)",
            },
          },
          splitArea: {
            show: false,
          },
          axisLine: {
            lineStyle: {
              color: "rgba(66, 139, 212, 0.3)",
            },
          },
        },
        series: [
          {
            name: "患者流量分布",
            type: "radar",
            data: [
              {
                value: [81, 90, 78, 60, 85, 70],
                name: "实际指标",
                lineStyle: {
                  color: "#5CACEE",
                },
                areaStyle: {
                  color: "rgba(92, 172, 238, 0.6)",
                },
              },
            ],
          },
        ],
      };

      this.charts.patientFlowChart.setOption(option);
    },

    updateVisitTrendChart() {
      if (!this.charts.visitTrendChart) {
        this.charts.visitTrendChart = echarts.init(this.$refs.visitTrendChart);
      }

      // 生成时间段数据
      const hours = [
        "00:00",
        "04:00",
        "08:00",
        "12:00",
        "16:00",
        "20:00",
        "24:00",
      ];
      const data = [120, 132, 301, 334, 290, 230, 150];

      const option = {
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true,
        },
        tooltip: {
          trigger: "axis",
          formatter: "{b}<br/>{a}: {c}人次",
        },
        xAxis: {
          type: "category",
          boundaryGap: false,
          data: hours,
          axisLine: {
            lineStyle: {
              color: "#666",
            },
          },
        },
        yAxis: {
          type: "value",
          name: "人次",
          axisLine: {
            lineStyle: {
              color: "#666",
            },
          },
        },
        series: [
          {
            name: "门诊人次",
            data: data,
            type: "line",
            areaStyle: {
              color: {
                type: "linear",
                x: 0,
                y: 0,
                x2: 0,
                y2: 1,
                colorStops: [
                  {
                    offset: 0,
                    color: "rgba(58, 132, 255, 0.6)",
                  },
                  {
                    offset: 1,
                    color: "rgba(58, 132, 255, 0.1)",
                  },
                ],
              },
            },
            lineStyle: {
              color: "#3A84FF",
              width: 2,
            },
            symbol: "circle",
            symbolSize: 6,
            itemStyle: {
              color: "#3A84FF",
            },
            smooth: true,
          },
        ],
      };

      this.charts.visitTrendChart.setOption(option);
    },

    updateWaitingTimeChart() {
      if (!this.charts.waitingTimeChart) {
        this.charts.waitingTimeChart = echarts.init(
          this.$refs.waitingTimeChart
        );
      }

      // 生成时间段数据
      const hours = [
        "00:00",
        "04:00",
        "08:00",
        "12:00",
        "16:00",
        "20:00",
        "24:00",
      ];
      const waitingData = [15, 25, 40, 30, 35, 20, 10];
      const consultingData = [20, 25, 30, 35, 30, 25, 20];

      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          formatter: function (params) {
            let result = params[0].axisValue + "<br/>";
            params.forEach((param) => {
              result += param.seriesName + ": " + param.value + "分钟<br/>";
            });
            return result;
          },
        },
        legend: {
          data: ["等待时间", "诊疗时间"],
          right: 10,
          textStyle: {
            color: "#fff",
          },
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true,
        },
        xAxis: {
          type: "category",
          data: hours,
          axisLine: {
            lineStyle: {
              color: "#666",
            },
          },
        },
        yAxis: {
          type: "value",
          name: "分钟",
          axisLine: {
            lineStyle: {
              color: "#666",
            },
          },
        },
        series: [
          {
            name: "等待时间",
            type: "line",
            data: waitingData,
            lineStyle: {
              color: "#3A84FF",
              width: 2,
            },
            symbol: "circle",
            symbolSize: 6,
            itemStyle: {
              color: "#3A84FF",
            },
            smooth: true,
          },
          {
            name: "诊疗时间",
            type: "line",
            data: consultingData,
            lineStyle: {
              color: "#FF6B6B",
              width: 2,
            },
            symbol: "circle",
            symbolSize: 6,
            itemStyle: {
              color: "#FF6B6B",
            },
            smooth: true,
          },
        ],
      };

      this.charts.waitingTimeChart.setOption(option);
    },

    // 疾病分布图表 - 更新为眼科疾病数据
    updateDiseaseDistributionChart() {
      if (!this.charts.diseaseDistributionChart) {
        this.charts.diseaseDistributionChart = echarts.init(
          this.$refs.diseaseDistributionChart
        );
      }

      const diseaseCategories = [
        "糖尿病视网膜病变",
        "青光眼",
        "白内障",
        "AMD",
        "高血压视网膜病变",
        "近视",
        "其他异常",
        "正常",
      ];

      // 眼科疾病分布数据
      const data = [
        { value: 95, name: "糖尿病视网膜病变" },
        { value: 83, name: "青光眼" },
        { value: 90, name: "白内障" },
        { value: 70, name: "AMD" },
        { value: 50, name: "高血压视网膜病变" },
        { value: 83, name: "近视" },
        { value: 50, name: "其他异常" },
        { value: 130, name: "正常" },
      ];

      const option = {
        tooltip: {
          trigger: "item",
          formatter: "{a} <br/>{b}: {c}例 ({d}%)",
        },
        legend: {
          orient: "vertical",
          right: 10,
          top: "center",
          data: diseaseCategories,
          textStyle: {
            color: "#fff",
          },
        },
        color: [
          "#FF5252", // 糖尿病
          "#7C4DFF", // 青光眼
          "#448AFF", // 白内障
          "#FFC107", // AMD
          "#FF9800", // 高血压
          "#00BCD4", // 近视
          "#9C27B0", // 其他异常
          "#4CAF50", // 正常
        ],
        series: [
          {
            name: "疾病分布",
            type: "pie",
            radius: ["50%", "70%"],
            avoidLabelOverlap: false,
            label: {
              show: false,
              position: "center",
            },
            emphasis: {
              label: {
                show: true,
                fontSize: "16",
                fontWeight: "bold",
              },
            },
            labelLine: {
              show: false,
            },
            data: data,
          },
        ],
      };

      this.charts.diseaseDistributionChart.setOption(option);
    },

    // 新增AI诊断准确率分析图表
    updateAccuracyChart() {
      if (!this.charts.accuracyChart) {
        this.charts.accuracyChart = echarts.init(this.$refs.accuracyChart);
      }

      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          formatter: "{b}<br/>{a}: {c}%",
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true,
        },
        xAxis: {
          type: "value",
          name: "准确率(%)",
          min: 0,
          max: 100,
          axisLabel: {
            formatter: "{value}%",
          },
        },
        yAxis: {
          type: "category",
          data: [
            "正常",
            "其他异常",
            "近视",
            "高血压视网膜病变",
            "AMD",
            "白内障",
            "青光眼",
            "糖尿病视网膜病变",
          ],
        },
        series: [
          {
            name: "准确率",
            type: "bar",
            data: [96, 84, 89, 86, 88, 92, 90, 94],
            itemStyle: {
              color: function (params) {
                const colorList = [
                  "#4CAF50", // 正常
                  "#9C27B0", // 其他异常
                  "#00BCD4", // 近视
                  "#FF9800", // 高血压
                  "#FFC107", // AMD
                  "#448AFF", // 白内障
                  "#7C4DFF", // 青光眼
                  "#FF5252", // 糖尿病
                ];
                return colorList[params.dataIndex];
              },
            },
            label: {
              show: true,
              position: "right",
              formatter: "{c}%",
            },
          },
        ],
      };

      this.charts.accuracyChart.setOption(option);
    },

    // 更新年龄分布图表
    updateAgeDistributionChart() {
      if (!this.charts.ageDistributionChart) {
        this.charts.ageDistributionChart = echarts.init(
          this.$refs.ageDistributionChart
        );
      }

      const ageGroups = ["0-18", "19-30", "31-45", "46-60", "61-75", "76+"];

      // 眼科患者年龄分布数据
      const normalData = [60, 75, 58, 40, 25, 20];
      const abnormalData = [15, 20, 50, 65, 80, 95];

      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow",
          },
          formatter: function (params) {
            let result = params[0].axisValue + "岁<br/>";
            params.forEach((param) => {
              result += param.seriesName + ": " + param.value + "人<br/>";
            });
            return result;
          },
        },
        legend: {
          data: ["正常", "异常"],
          textStyle: {
            color: "#fff",
          },
        },
        grid: {
          left: "3%",
          right: "4%",
