    updateAnomalyCases() {
      // 生成模拟异常病例数据
      this.anomalyCases = [];

      for (let i = 0; i < 5; i++) {
        const date = new Date();
        date.setDate(date.getDate() - Math.floor(Math.random() * 30));

        const leftConfidence = Math.floor(Math.random() * 30) + 40; // 40-70之间
        const rightConfidence = Math.floor(Math.random() * 30) + 40;

        const diseaseOptions = [
          "糖尿病视网膜病变",
          "青光眼",
          "白内障",
          "AMD",
          "高血压视网膜病变",
          "近视",
          "其他异常",
          "正常",
        ];

        const leftDiagnosis =
          diseaseOptions[Math.floor(Math.random() * diseaseOptions.length)];
        const rightDiagnosis =
          diseaseOptions[Math.floor(Math.random() * diseaseOptions.length)];

        let anomalyReason;
        if (leftConfidence < 60 && rightConfidence < 60) {
          anomalyReason = "双眼诊断置信度低";
        } else if (leftConfidence < 60) {
          anomalyReason = "左眼诊断置信度低";
        } else if (rightConfidence < 60) {
          anomalyReason = "右眼诊断置信度低";
        } else if (
          leftDiagnosis !== rightDiagnosis &&
          leftDiagnosis !== "正常" &&
          rightDiagnosis !== "正常"
        ) {
          anomalyReason = "左右眼诊断结果差异大";
        }

        this.anomalyCases.push({
          id: `EYE2023${2000 + i}`,
          time: date.toLocaleString(),
          leftEye: {
            diagnosis: leftDiagnosis,
            confidence: leftConfidence,
          },
          rightEye: {
            diagnosis: rightDiagnosis,
            confidence: rightConfidence,
          },
          anomalyReason: anomalyReason,
        });
      }
    },
